insert into RSK_EVENT_ITEM_RULE (EVENT_CODE, ITEM_CODE, ITEM_ANO_NAME, MATCH_TYPE, OFFSET_VAL, OFFSET_TYPE, OFFSET_UNIT, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME, ITEM_VALUE) select t1.eventCode, t1.itemCode, t1.itemAnoName, t1.matchType, t1.offsetVal, t1.offsetType, t1.offsetUnit, t1.createUser, t1.createDept, t1.createTime, t1.updateUser, t1.updateTime, t1.itemValue from (
select #{item.eventCode,jdbcType=VARCHAR} eventCode, #{item.itemCode,jdbcType=VARCHAR} itemCode, #{item.itemAnoName,jdbcType=VARCHAR} itemAnoName, #{ item.matchType,jdbcType=VARCHAR} matchType, #{item.offsetVal,jdbcType=DECIMAL} offsetVal, #{item.offsetType,jdbcType=VARCHAR} offsetType, #{item.offsetUnit,jdbcType=VARCHAR} offsetUnit, #{ item.createUser,jdbcType=VARCHAR} createUser, #{item.createDept,jdbcType=VARCHAR} createDept, #{item.createTime,jdbcType=TIMESTAMP} createTime, #{item.updateUser,jdbcType=VARCHAR} updateUser, #{item.updateTime,jdbcType=TIMESTAMP} updateTime, #{item.itemValue,jdbcType=CLOB} itemValue from dual
) t1

